solution:
balance = 10000
while True:
    menu = int(input("메뉴 선택 (1: 조회, 2: 입금, 3: 출금, 0: 종료): "))
    if menu == 0:
        print("감사합니다")
        break
    if menu == 1:
        print("잔액:", balance)
    elif menu == 2:
        amount = int(input("입금액: "))
        balance += amount
        print("잔액:", balance)
    elif menu == 3:
        amount = int(input("출금액: "))
        if amount > balance:
            print("잔액 부족")
        else:
            balance -= amount
        print("잔액:", balance)
